 if rule['creatorAbsent']:steps.append(Step(name='deleted-original-C-Get',method='GET',path='/iam/v1/serviceAccounts/{{rid11Creator}}',auth='jwtRIDOperator',test_script=[*assert_status(404),"pm.test('same original C absent; no identity substitution',()=>{const j=pm.response.json();pm.expect(j.code).to.eql(5);pm.expect(j.id).to.eql(undefined);});"]))
